import React from 'react';
import { NavLink } from 'react-router-dom';
import { accessibleNavSections } from '../navigation';

const Sidebar = ({ isOpen, isCollapsed, onClose, onToggleCollapse, currentUser, onLogout }) => {
  const sections = accessibleNavSections(currentUser?.role || 'employee');
  const getBadge = (item) => {
    if (item.badge === 'unread') return currentUser?.unread_chat_count;
    if (item.badge === 'pendingApprovals') return currentUser?.pending_approval_count;
    return null;
  };

  return (
    <>
      <button className={`shell-backdrop ${isOpen ? 'visible' : ''}`} aria-label="Close navigation" onClick={onClose} type="button" />
      <aside className={`app-sidebar ${isOpen ? 'open' : ''} ${isCollapsed ? 'collapsed' : ''}`} aria-label="Primary navigation">
        <div className="sidebar-brand">
          <button className="sidebar-collapse-toggle" type="button" onClick={onToggleCollapse} aria-label="Toggle sidebar">
            <span aria-hidden="true">◀</span>
          </button>
          <div className="brand-mark"><img src="/Okoafloat.png" alt="Okoa Float" className="brand-logo" /></div>
        </div>
        <nav className="sidebar-nav" aria-label="Sidebar navigation">
          {sections.map((section) => (
            <React.Fragment key={section.title}>
              {!isCollapsed && <div className="nav-label">{section.title}</div>}
              {section.items.map(({ label, icon: Icon, path, action, badge }) => {
                const count = getBadge({ badge });
                if (action === 'logout') {
                  return <button key={path} className="sidebar-link sidebar-button" type="button" onClick={onLogout} aria-label={label}><Icon size={16} aria-hidden="true" /><span>{label}</span></button>;
                }
                return (
                  <NavLink
                    key={path}
                    to={path}
                    end={path === '/dashboard' || path === '/hr'}
                    className={({ isActive }) => `sidebar-link ${isActive ? 'active' : ''}`}
                    onClick={onClose}
                    aria-label={label}
                  >
                    <Icon size={16} aria-hidden="true" />
                    <span>{label}</span>
                    {count ? <span className="sidebar-badge" aria-label={`${count} pending`}>{count}</span> : null}
                  </NavLink>
                );
              })}
            </React.Fragment>
          ))}
        </nav>
      </aside>
    </>
  );
};

export default Sidebar;
